    public void testarOuroNaoPagaFrete() {
        List<ItemDto> itens = new ArrayList<>();
        itens.add(criarItem("Item", new BigDecimal("100.00"), 1, new BigDecimal("2.00")));

        Object resultado = service.calcularResumo(
